insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-01','nieuw','Planning','Planning uit EVA komt nu ook in Bouw7',
   'Plan je iemand in via de detailplanning of de medewerkerplanning, dan verschijnt die planning voortaan automatisch in Bouw7. Verplaats je een klus of haal je iemand eraf, dan gaat die wijziging mee; verwijder je hem, dan verdwijnt hij ook daar. Je hoeft dus niet langer op twee plekken hetzelfde in te voeren.'),
  ('2026-09-01','opgelost','Planning','Medewerkerplanning toont weer de volledige planning',
   'Bij drukke weken viel een deel van de planning weg uit het overzicht: sommige collega''s leken een lege agenda te hebben terwijl er wel degelijk werk voor ze stond. Het scherm laadde namelijk maar een beperkt aantal regels. Dat is opgelost — je ziet nu altijd alle ingeplande klussen.');
